def bs(a, t):
    lo, hi = 0, len(a) - 1
    steps = 0
    while lo <= hi:
        steps += 1
        mid = (lo + hi) // 2
        if a[mid] == t:
            return mid, steps
        elif a[mid] < t:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1, steps

